{"results": [{"id": "hp_doc_78b652098744f8195a39056dcc7cf93c1e38b1de0315992f7d187a92b78cdeb2", "title": "Gateway Fashion Mall", "text": "Gateway Fashion Mall (formerly Gateway Mall) is an enclosed shopping mall in Bismarck, North Dakota. Opened in 1979, the mall has more than 30 stores, with Hancock Fabrics and Sears as anchor stores.", "score": 32.8204}, {"id": "hp_doc_352d072d46ce87d7326f3c65b2088011ae521c86308af99e08763ee11c63a8fc", "title": "U.S. Fashion", "text": "U.S. Fashion Mall is a shopping mall located on the Ashram Road in Gariyadhar, Bhavnagar, and is owned by Mr. Vaghani The mall spans 1888151 sqft of space, with more than 250 stores and seven anchors, and hosts weekend fashion shows on a retractable runway with the mall's central atrium, hence the name.", "score": 18.655}, {"id": "hp_doc_81cbea0543594e29a9172a2d97b62a83cfa197a042993ee40e69195141482692", "title": "Kenanga Wholesale City", "text": "Kenanga Wholesale City (also known as KWC Fashion Mall), is Malaysia's first fashion wholesale mall. It is located in the heart of Kuala Lumpur, a few minutes from the city's Golden Triangle, in the fashion wholesale area of Jalan Kenanga.", "score": 18.458}], "remaining_searches": 2}
