{"results": [{"id": "hp_doc_1aeb40ba57a4dfe50baeaecc53132675b0e54957b43d58d74edafda65877c840", "title": "Hancock Fabrics", "text": "Hancock Fabrics was a specialty retailer of crafts and fabrics based in Baldwyn, Mississippi, United States. Hancock Fabrics operated as many as 266 stores in 37 states under the Hancock Fabrics name. Hancock Fabrics was established by the late Lawrence D. Hancock. All stores are in bankruptcy liquidation.", "score": 36.0728}, {"id": "hp_doc_78b652098744f8195a39056dcc7cf93c1e38b1de0315992f7d187a92b78cdeb2", "title": "Gateway Fashion Mall", "text": "Gateway Fashion Mall (formerly Gateway Mall) is an enclosed shopping mall in Bismarck, North Dakota. Opened in 1979, the mall has more than 30 stores, with Hancock Fabrics and Sears as anchor stores.", "score": 18.1163}, {"id": "hp_doc_d93c9c1d8bfe5bf9b4e42259d694398b67287c6df06562424709bb72fd248f44", "title": "Hancock, Pennsylvania", "text": "Hancock is an unincorporated community in Longswamp Township in Berks County, Pennsylvania, United States. Hancock is located at the intersection of State Street and Park Avenue.", "score": 12.1993}], "remaining_searches": 1}
